  static int NextBirthday(string date){var born=DateTime.ParseExact(date,"yyyy-MM-dd",null);int day=Math.Min(born.Day,DateTime.DaysInMonth(DateTime.Today.Year,born.Month));var next=new DateTime(DateTime.Today.Year,born.Month,day);if(next<DateTime.Today){int y=DateTime.Today.Year+1;next=new DateTime(y,born.Month,Math.Min(born.Day,DateTime.DaysInMonth(y,born.Month)));}return (next-DateTime.Today).Days;}
  static string Groups(IEnumerable<string> list){var groups=list.Where(x=>!String.IsNullOrWhiteSpace(x)).GroupBy(x=>x).OrderByDescending(x=>x.Count()).Take(12).Select(x=>x.Key+" "+x.Count()+"人");return groups.Any()?String.Join("　",groups):"尚未记录";}
