  void FilterMembers(){filtering=true;string previous=selected;string q=search.Text.Trim();memberGrid.Rows.Clear();foreach(var p in Store.Data.People.Where(p=>(sex.SelectedIndex==0||p.Gender==sex.Text)&&String.Join(" ",new[]{p.Name,p.Birth,p.Death,p.Place,p.Address,p.Phone,p.Occupation,p.Generation,p.Biography,Store.Name(p.FatherId),Store.Name(p.MotherId)}).IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0).OrderBy(p=>p.Name)){int row=memberGrid.Rows.Add(p.Name,p.Gender,p.Birth,p.Generation,p.Place,Store.Name(p.FatherId),Store.Name(p.MotherId));memberGrid.Rows[row].Tag=p.Id;if(p.Id==previous)memberGrid.CurrentCell=memberGrid.Rows[row].Cells[0];}filtering=false;selected=SelectedKey(memberGrid)??"";ShowDetail();status.Text="找到 "+memberGrid.Rows.Count+" / "+Store.Data.People.Count+" 位成员  ·  搜索覆盖姓名、日期、籍贯、职业、生平等档案内容";}
