   DataGroup(flow,"导出与印刷","JSON 保存结构化档案，CSV 便于表格查看，GEDCOM 用于其他家谱软件。后三种不打包附件；HTML 家谱册不含联系方式和住址。",Ui.Button("导出 JSON",()=>Export("JSON 数据|*.json","家谱档案.json",Store.ExportJson)),Ui.Button("成员 CSV",()=>Export("CSV 表格|*.csv","成员名册.csv",Store.ExportCsv)),Ui.Button("GEDCOM",()=>Export("GEDCOM|*.ged","家谱.ged",Store.ExportGed)),Ui.Button("HTML 家谱册",()=>{string f=Ui.SavePath("HTML 家谱册|*.html","家谱册.html");if(f!=null){Reports.ExportHtml(f);Ui.Open(f);}}));
   DataGroup(flow,"导入与新建","JSON / GEDCOM 导入替换当前家谱；新建及示例会新增独立家谱。JSON 不恢复头像及附件。GEDCOM 支持姓名、性别、生卒、父母、配偶、籍贯扩展和备注；不支持的字段会忽略。",Ui.Button("导入 JSON",()=>{string f=Ui.OpenPath("JSON 数据|*.json");if(f==null)return;var d=new JavaScriptSerializer{MaxJsonLength=50*1024*1024}.Deserialize<FamilyData>(File.ReadAllText(f));foreach(var p in d.People)p.Portrait="";d.Documents.Clear();Store.Validate(d);if(Ui.Confirm("导入 "+d.People.Count+" 人并替换当前家谱？JSON 不包含附件；当前数据会先自动备份。")){Store.Replace(d,null);Navigate(current);}}),Ui.Button("导入 GEDCOM",()=>{string f=Ui.OpenPath("GEDCOM|*.ged");if(f==null)return;var d=Store.ImportGed(f);if(Ui.Confirm("导入 "+d.People.Count+" 人并替换当前家谱？仅导入支持的基础字段，当前数据会先自动备份。")){Store.Replace(d,null);Navigate(current);}}),Ui.Button("新增示例家谱",()=>CreateFamily(true)),Ui.Button("新建家谱",()=>CreateFamily(false)));
   DataGroup(flow,"本地存储与检查","数据目录："+Store.Root+"\r\n每次保存保留一份 family.xml.previous；替换前的完整备份在 backups 文件夹。卸载默认保留家谱数据。",Ui.Button("打开数据目录",()=>Ui.Open(Store.Root)),Ui.Button("打开自动备份",()=>{string dir=Path.Combine(Store.Root,"backups");Directory.CreateDirectory(dir);Ui.Open(dir);}),Ui.Button("检查数据完整性",()=>{Store.Validate(Store.Data);var missing=Store.Data.People.Select(p=>p.Portrait).Concat(Store.Data.Documents.Select(d=>d.File)).Where(f=>f!=""&&!File.Exists(Path.Combine(Store.Root,f))).ToList();Ui.Info(missing.Count==0?"检查通过：亲属关系、日期与附件均正常。":"发现 "+missing.Count+" 个缺失附件，请从完整备份恢复。");}));
  }
  void Workbench(){Heading("编修工作台","把线索变成档案：补全资料、核实日期、清理重复、记录待办。所有提示均需人工判断。");Toolbar(Ui.Button("批量完善档案",()=>{using(var w=new BulkEditor())if(w.ShowDialog(this)==DialogResult.OK)Navigate(current);},true),Ui.Button("导出可编辑表格",()=>Export("Excel 工作簿|*.xlsx","景·谱-可编辑档案.xlsx",Templates.ExportEditable)),Ui.Button("恢复上次保存",()=>{var d=Workshop.Previous();if(Ui.Confirm("恢复上一次保存（"+d.People.Count+" 位成员）？当前内容会先创建完整备份。")){Store.Replace(d,null);Navigate(current);}}));Fill(new WorkbenchPanel(id=>{selected=id;EditSelected();}));}
  void Export(string filter,string name,Action<string> action){string f=Ui.SavePath(filter,name);if(f!=null){action(f);Ui.Info("已导出："+f);}}
  void DataGroup(FlowLayoutPanel flow,string title,string text,params Control[] buttons){var box=new RoundedSurface{Width=Math.Max(620,page.ClientSize.Width-page.Padding.Horizontal-20),Height=168,Margin=new Padding(0,0,0,18)};var h=Ui.Label(title,12,true);h.Location=new Point(22,18);box.Controls.Add(h);var p=Ui.Label(text,9.5f);p.ForeColor=StudioStyle.Muted;p.Location=new Point(22,53);box.Controls.Add(p);var tools=new FlowLayoutPanel{Location=new Point(22,100),Width=box.Width-44,Height=48,WrapContents=true,BackColor=Color.White};tools.Controls.AddRange(buttons);box.Controls.Add(tools);bool resizing=false;Action arrange=()=>{if(resizing)return;resizing=true;p.MaximumSize=new Size(Math.Max(200,box.Width-44),0);tools.Top=53+p.PreferredHeight+17;tools.Width=box.Width-44;tools.Height=Math.Max(46,tools.GetPreferredSize(new Size(tools.Width,0)).Height);box.Height=tools.Bottom+19;resizing=false;};box.SizeChanged+=(s,e)=>arrange();flow.Controls.Add(box);arrange();}
  void About(){Heading("关于景·谱","让家族记忆有迹可循，让每一个名字被记住。");var body=new Panel{Dock=DockStyle.Fill,AutoScroll=true};Fill(body);var stack=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1};stack.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));body.Controls.Add(stack);AddSection(stack,"景·谱  1.5.0","一款支持管理多个独立家谱的离线中文工具，将成员档案、亲缘关系、世系图、大事记与家族资料汇集于一处。\r\n适合家庭记录、族谱整理与家风传承。所有内容由使用者自行编修，软件不会自动判断历史真实性。\r\n运行环境：Windows 10 / 11，系统 .NET Framework 4.5 或更高版本。无需联网、无需注册。");AddSection(stack,"功能一览","多家谱管理 · 独立附件及备份 · 回收恢复及永久删除\r\n成员档案 · 亲缘路径查询 · 多配偶与父母子女关系 · 头像与生平 · 全文检索与筛选\r\n家庭组世系图 · 三套主题 · 详细/紧凑卡片 · 照片 · 祖先/后代/近亲视图\r\nSVG / EMF 矢量导出 · 交互网页 · 高清/透明 PNG · 分页打印 / PDF\r\n快捷添加亲属 · 编修工作台 · 重复合并 · 批量补全 · 编修待办\r\n家族事件 · 资料附件 · 生日 / 忌日提醒 · 字辈与籍贯统计\r\n可编辑 Excel 导出与按编号回填 · Excel / CSV 模板下载及导入 · JSON / GEDCOM 导入导出 · CSV 导出 · HTML 家谱册 · ZIP 完整备份恢复");AddSection(stack,"联系作者","微信公众号：景同志\r\n小红书：景同学\r\n\r\n欢迎交流软件使用体验与家谱编修心得。请在对应平台搜索以上名称联系作者。");var links=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};links.Controls.Add(Ui.Button("复制微信公众号",()=>{Clipboard.SetText("景同志");Ui.Info("已复制：景同志");},true));links.Controls.Add(Ui.Button("复制小红书名称",()=>{Clipboard.SetText("景同学");Ui.Info("已复制：景同学");}));stack.Controls.Add(links);AddSection(stack,"开源与下载","景·谱已在 GitHub 开源，可在此获取最新版本、查看完整源码、提交问题或参与改进。\r\n项目地址："+GitHubUrl);var gh=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};gh.Controls.Add(Ui.Button("打开 GitHub 仓库",()=>Ui.Open(GitHubUrl),true));gh.Controls.Add(Ui.Button("复制仓库地址",()=>{Clipboard.SetText(GitHubUrl);Ui.Info("已复制："+GitHubUrl);}));stack.Controls.Add(gh);AddSection(stack,"使用与数据说明","本软件不上传家谱内容。请在录入在世亲属的联系方式、住址、照片前征得对方同意。\r\n完整备份及 JSON 含个人档案，未加密，请保存在可信位置。CSV 亦包含联系方式。\r\n生日按公历计算；日期未知可只填年或年月。GEDCOM 以 UTF-8 读写，兼容基础人物和家庭关系。\r\n图谱按家庭组和亲子层级排布；复杂交叉关系可能保留交叉连线。可按分支或层数浏览。\r\n系统打印可选择已安装的 PDF 打印机。附件需系统中对应的程序打开。");}
 }
 public static class Program {
  [STAThread] public static int Main(string[] args){if(args.Contains("--self-test"))return Tests.Run(args);if(args.Length==2&&args[0]=="--export-templates"){Templates.ExportBundle(args[1]);return 0;}if(args.Length==2&&args[0]=="--data-dir")Store.Root=Path.GetFullPath(args[1]);bool created;using(var mutex=new System.Threading.Mutex(true,"Local\\JingFamilyDesktop",out created)){if(!created){Ui.Info("景·谱已在运行。请切换到已打开的窗口。");return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.ThreadException+=(s,e)=>Ui.Error(e.Exception);try{Library.Initialize(Store.Root);}catch(Exception ex){Ui.Info("家谱文件未能读取，软件将退出以保护原文件。\n"+ex.GetBaseException().Message+"\n\n数据目录："+Store.Root+"\n可将 family.xml.previous 复制为 family.xml，或从完整备份恢复。\n多家谱目录索引：library.xml；索引上次保存：library.xml.previous。");return 1;}Application.Run(new MainWindow());return 0;}}
 }
